import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { isSvgPath, looksLikeSvg, svgDataUri, FIT, PICTURE_ZOOMS, fitScale, stepPictureZoom, zoomLabel } from '../src/workspace/picture.js';

// What Graphviz writes (dot -Tsvg), cut short: a declaration, a DOCTYPE, comments, then the svg element.
const graphviz = `<?xml version="1.0" encoding="UTF-8" standalone="no"?>
<!DOCTYPE svg PUBLIC "-//W3C//DTD SVG 1.1//EN"
 "http://www.w3.org/Graphics/SVG/1.1/DTD/svg11.dtd">
<!-- Generated by graphviz version 2.43.0 (0)
 -->
<!-- Title: G Pages: 1 -->
<svg width="170pt" height="52pt" viewBox="0.00 0.00 170.00 52.00" xmlns="http://www.w3.org/2000/svg">
<g id="graph0" class="graph"><title>Autómata #1 &#45;&gt; 100%</title></g>
</svg>
`;

test('a file is a picture by its name: .svg in any case, and nothing else', () => {
  for (const path of ['a.svg', 'automaton.SVG', 'dir/a.svg', 'out/lexer/dfa.Svg']) assert.ok(isSvgPath(path), path);
  for (const path of ['a.svgz', 'svg', 'a.svg.txt', 'a.png', 'svg/a.txt', '', null, undefined]) assert.ok(!isSvgPath(path), String(path));
});

test('the text looks like an SVG when its first element is <svg', () => {
  assert.ok(looksLikeSvg(graphviz));
  assert.ok(looksLikeSvg(`﻿${graphviz}`), 'with a byte order mark');
  assert.ok(looksLikeSvg('<svg xmlns="http://www.w3.org/2000/svg"/>'));
  assert.ok(looksLikeSvg('  \n<svg>\n</svg>'));
  assert.ok(looksLikeSvg('<?xml version="1.0"?>\n<?xml-stylesheet href="a.css"?>\n<svg width="1" height="1"></svg>'));
  // A DOCTYPE with declarations of its own, which hold a >.
  assert.ok(looksLikeSvg('<!DOCTYPE svg [ <!ENTITY a "<g>"> ]>\n<svg></svg>'));
  // An empty comment, and a comment right before the element.
  assert.ok(looksLikeSvg('<!----><svg/>'));
  for (const text of ['', '   ', 'plain text\n', 'This file is about the <svg> element.\n', '<!DOCTYPE html>\n<html><body><svg></svg></body></html>',
    '<html><svg></svg></html>', '<svgx></svgx>', '<?xml version="1.0"?>', '<!-- never closed <svg>', '<!DOCTYPE svg [ <svg>', '\0\0\0', 'digraph G { a -> b }']) {
    assert.ok(!looksLikeSvg(text), JSON.stringify(text));
  }
  assert.ok(!looksLikeSvg(null) && !looksLikeSvg(undefined));
});

test('the address of the picture is a data: address that keeps the text as it is', () => {
  const address = svgDataUri(graphviz);
  assert.ok(address.startsWith('data:image/svg+xml;charset=utf-8,'));
  const body = address.slice(address.indexOf(',') + 1);
  // A # would end the address, and a lone % would break it: neither is left as it is.
  assert.ok(!body.includes('#'));
  assert.ok(!/%(?![0-9A-F]{2})/.test(body));
  assert.ok(!/[\s<>"]/.test(body));
  assert.equal(decodeURIComponent(body), graphviz);
  assert.ok(decodeURIComponent(body).includes('Autómata #1 &#45;&gt; 100%'));
});

test('a text the encoder would refuse, or one of 1 MiB, still makes an address', () => {
  assert.equal(decodeURIComponent(svgDataUri('a\uD800b\uDC00c').split(',')[1]), 'a�b�c');
  assert.equal(decodeURIComponent(svgDataUri('😀').split(',')[1]), '😀');
  const big = `<svg xmlns="http://www.w3.org/2000/svg">${'<text>Autómata #% 😀</text>\n'.repeat(40000)}</svg>`.slice(0, 1 << 20);
  const address = svgDataUri(big);
  assert.ok(address.length > big.length);
  assert.equal(decodeURIComponent(address.split(',')[1]), big.replace(/[\uD800-\uDBFF]$/, '�'));
});

test('Fit scales a picture down to the room and never up', () => {
  assert.equal(fitScale(3000, 300, 1000, 600), 1000 / 3000);
  assert.equal(fitScale(300, 3000, 1000, 600), 600 / 3000);
  assert.equal(fitScale(200, 100, 1000, 600), 1);
  assert.equal(fitScale(0, 100, 1000, 600), 1);
  assert.ok(fitScale(3000, 3000, 0, 0) > 0, 'a room with no size yet');
});

test('the zoom steps are of the picture\'s own size, end at both ends, and 0 is Fit', () => {
  assert.deepEqual(PICTURE_ZOOMS, [0.5, 0.75, 1, 1.5, 2, 3, 4]);
  assert.ok(PICTURE_ZOOMS.includes(1));
  assert.equal(stepPictureZoom(1, 1, 1), 1.5);
  assert.equal(stepPictureZoom(1, 1, -1), 0.75);
  assert.equal(stepPictureZoom(2, 2, 0), FIT);
  assert.equal(stepPictureZoom(FIT, 0.3, 0), FIT);
  // From Fit, + is the next step larger than what Fit draws at, and − the next smaller.
  assert.equal(stepPictureZoom(FIT, 0.3, 1), 0.5);
  assert.equal(stepPictureZoom(FIT, 0.8, 1), 1);
  assert.equal(stepPictureZoom(FIT, 0.8, -1), 0.75);
  // At the ends the zoom stays where it is, Fit included.
  assert.equal(stepPictureZoom(4, 4, 1), 4);
  assert.equal(stepPictureZoom(0.5, 0.5, -1), 0.5);
  assert.equal(stepPictureZoom(FIT, 0.3, -1), FIT);
  assert.equal(stepPictureZoom(FIT, 1, 1), 1.5);
  assert.equal(zoomLabel(1), '100 %');
  assert.equal(zoomLabel(1000 / 3000), '33 %');
});

test('the picture is an <img> from a data: address, never the SVG put into the page', () => {
  const view = readFileSync(new URL('../src/workspace/PictureView.svelte', import.meta.url), 'utf8');
  const markup = view.replace(/<script>[\s\S]*?<\/script>|<style>[\s\S]*?<\/style>|<!--[\s\S]*?-->/g, '');
  assert.ok(/<img src=\{shown\.address\}/.test(markup));
  assert.ok(/draggable="false"/.test(markup));
  for (const pattern of [/\{@html/, /<iframe/i, /<object/i, /<embed/i, /innerHTML/, /createObjectURL/, /blob:/]) assert.ok(!pattern.test(view), String(pattern));
  // The page allows data: images and no blob: ones; the picture depends on it.
  const csp = readFileSync(new URL('../index.html', import.meta.url), 'utf8').match(/Content-Security-Policy" content="([^"]+)"/)[1];
  assert.match(csp, /img-src 'self' data:/);
});
